package dispatcher

import (
	"context"
	"encoding/hex"
	"testing"

	"github.com/xtls/xray-core/common"
	"github.com/xtls/xray-core/common/net"
	"github.com/xtls/xray-core/common/protocol"
	"github.com/xtls/xray-core/common/serial"
	"github.com/xtls/xray-core/core"
)

// instanceContext returns a context that carries a running xray instance, as
// the dispatcher's own context does; NewSniffer looks the FakeDNS engine up
// in it. SessionConfig is registered by nothing else, so it can serve as the
// hook through which the instance hands that context over.
func instanceContext(t *testing.T) context.Context {
	t.Helper()
	var captured context.Context
	common.Must(common.RegisterConfig((*SessionConfig)(nil), func(ctx context.Context, _ interface{}) (interface{}, error) {
		captured = ctx
		return nil, nil
	}))
	inst, err := core.New(&core.Config{App: []*serial.TypedMessage{serial.ToTypedMessage(&SessionConfig{})}})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { inst.Close() })
	return captured
}

// A QUIC Initial whose ClientHello does not fit in one packet - the norm for
// Chrome and Firefox since they send post-quantum key shares. The first
// packet alone must report "matches, need more data" so the dispatcher keeps
// reading; answering with a plain error ends sniffing, and the panel's domain
// rules never see HTTP/3 traffic.
func TestSniffQUICAcrossPackets(t *testing.T) {
	pkts, err := hex.DecodeString("")
	if err != nil {
		t.Fatal(err)
	}
	first := make([]byte, 1250)
	copy(first, pkts)

	ctx := instanceContext(t)
	s := NewSniffer(ctx)
	if _, err := s.Sniff(ctx, first, net.Network_UDP); err != protocol.ErrProtoNeedMoreData {
		t.Fatalf("first packet: err = %v, want %v", err, protocol.ErrProtoNeedMoreData)
	}
	result, err := NewSniffer(ctx).Sniff(ctx, pkts, net.Network_UDP)
	if err != nil {
		t.Fatalf("both packets: %v", err)
	}
	if result.Protocol() != "quic" || result.Domain() != "play.google.com" {
		t.Fatalf("got %s %q, want quic play.google.com", result.Protocol(), result.Domain())
	}
}
